'use client'

import { useEffect } from 'react'

/**
 * Registers the service worker generated by `scripts/build-sw.mjs`.
 *
 * The `@ducanh2912/next-pwa` plugin used to inject this registration
 * automatically via its `register: true` option. That plugin was removed
 * because it corrupted the Next.js server webpack graph during static export,
 * so registration now has to be performed explicitly.
 */
export default function ServiceWorkerRegistrar() {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production') return
    if (typeof window === 'undefined' || !('serviceWorker' in navigator)) return

    const onLoad = () => {
      navigator.serviceWorker.register('/sw.js').catch((error) => {
        console.error('Service worker registration failed:', error)
      })
    }

    if (document.readyState === 'complete') {
      onLoad()
    } else {
      window.addEventListener('load', onLoad)
      return () => window.removeEventListener('load', onLoad)
    }
  }, [])

  return null
}
